from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime
from typing import Any

from packaging.specifiers import InvalidSpecifier, SpecifierSet
from packaging.version import InvalidVersion, Version


def _parse_iso_8601(value: Any) -> datetime | None:
    """Parse a PyPI ``upload_time_iso_8601`` value, returning ``None`` on failure."""
    if not isinstance(value, str) or not value:
        return None
    try:
        # ``datetime.fromisoformat`` on older Pythons does not accept a trailing
        # ``Z``, so normalize it to an explicit UTC offset first.
        return datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None


@dataclass(frozen=True)
class Release:
    """A single package release (one version)."""

    upload_time: datetime
    yanked: bool
    requires_python: SpecifierSet | None

    @classmethod
    def from_distributions(cls, distributions: list[dict[str, Any]]) -> Release | None:
        """Build a :class:`Release` from its list of distribution dicts.

        Returns ``None`` when the release should be dropped, i.e. when no
        distribution carries a parseable ``upload_time_iso_8601`` field.
        """
        upload_times = [
            t
            for d in distributions
            if (t := _parse_iso_8601(d.get("upload_time_iso_8601"))) is not None
        ]
        if not upload_times:
            return None

        # A release is considered yanked only when every distribution is yanked.
        yanked = all(bool(d.get("yanked", False)) for d in distributions)

        requires_python: SpecifierSet | None = None
        for d in distributions:
            raw = d.get("requires_python")
            if not raw:
                continue
            try:
                requires_python = SpecifierSet(raw)
            except InvalidSpecifier:
                continue
            break

        return cls(
            upload_time=min(upload_times),
            yanked=yanked,
            requires_python=requires_python,
        )


@dataclass
class Package:
    """A PyPI package and its releases."""

    name: str
    releases: dict[Version, Release] = field(default_factory=dict)

    @classmethod
    def from_json(cls, data: dict[str, Any]) -> Package:
        """Parse a PyPI JSON API response into a :class:`Package`.

        Releases are dropped when they have no distributions, when no
        distribution has a parseable ``upload_time_iso_8601`` field, or when the
        version string is not a valid PEP 440 version.
        """
        info = data.get("info") or {}
        name = info.get("name", "")

        releases: dict[Version, Release] = {}
        for version_str, distributions in (data.get("releases") or {}).items():
            if not distributions:
                continue
            try:
                version = Version(version_str)
            except InvalidVersion:
                continue
            release = Release.from_distributions(distributions)
            if release is None:
                continue
            releases[version] = release

        return cls(name=name, releases=releases)

    @property
    def versions(self) -> tuple[Version, ...]:
        """All valid release versions, sorted in ascending order."""
        return tuple(sorted(self.releases))

    @property
    def latest_version(self) -> Version | None:
        """Highest stable (non-pre-release, non-dev, non-yanked) version, or ``None``."""
        stable = [
            version
            for version in self.versions
            if not version.is_prerelease
            and not version.is_devrelease
            and not self.releases[version].yanked
        ]
        return stable[-1] if stable else None

    def get_release(self, version: str | Version) -> Release | None:
        """Return the :class:`Release` for ``version``, or ``None`` if absent."""
        if isinstance(version, str):
            try:
                version = Version(version)
            except InvalidVersion:
                return None
        return self.releases.get(version)
