from __future__ import annotations

import asyncio
import json
import os
import time
from typing import Iterable
from urllib.error import HTTPError, URLError
from urllib.request import urlopen

from pypi._models import Package

# Status codes that indicate a transient failure worth retrying.
_RETRYABLE_STATUS = frozenset({429, 500, 502, 503, 504})
# Maximum total number of attempts (initial request + retries).
_MAX_ATTEMPTS = 3
# Default base URL for the PyPI JSON API.
_DEFAULT_BASE_URL = "https://pypi.org"


class PyPIError(RuntimeError):
    """Raised for all unrecoverable errors when fetching from PyPI."""


# In-memory cache mapping package name -> parsed ``Package``.
_cache: dict[str, Package] = {}


def _base_url() -> str:
    return os.environ.get("PYPI_URL", _DEFAULT_BASE_URL).rstrip("/")


def _build_url(name: str) -> str:
    return f"{_base_url()}/pypi/{name}/json"


def _fetch_json(name: str) -> dict:
    """Fetch and decode the JSON metadata for ``name``, retrying transient errors."""
    url = _build_url(name)
    last_error: Exception | None = None

    for attempt in range(_MAX_ATTEMPTS):
        try:
            with urlopen(url) as response:
                body = response.read()
            data = json.loads(body)
            if not isinstance(data, dict):
                raise PyPIError(
                    f"Unexpected response for {name!r}: expected a JSON object, "
                    f"got {type(data).__name__}"
                )
            return data
        except HTTPError as e:
            if e.code == 404:
                raise PyPIError(f"Package not found: {name!r}") from e
            if e.code not in _RETRYABLE_STATUS:
                raise PyPIError(f"HTTP {e.code} while fetching {name!r}") from e
            last_error = e
        except (URLError, ConnectionResetError) as e:
            last_error = e

        # A retryable failure occurred; sleep before the next attempt (if any).
        if attempt < _MAX_ATTEMPTS - 1:
            time.sleep(2**attempt)

    raise PyPIError(
        f"Failed to fetch {name!r} after {_MAX_ATTEMPTS} attempts"
    ) from last_error


def get_package(name: str) -> Package:
    """Fetch package metadata from the PyPI JSON API, memoizing results in memory."""
    if name in _cache:
        return _cache[name]
    package = Package.from_json(_fetch_json(name))
    _cache[name] = package
    return package


def clear_cache() -> None:
    """Clear the in-memory cache used by :func:`get_package`."""
    _cache.clear()


async def aget_package(name: str) -> Package:
    """Async wrapper around :func:`get_package`."""
    return await asyncio.to_thread(get_package, name)


async def aget_packages(names: Iterable[str]) -> list[Package]:
    """Fetch multiple packages concurrently, preserving input order."""
    return list(await asyncio.gather(*(aget_package(name) for name in names)))
